package africa.growtogether.platform.eiam.mfa;
import africa.growtogether.platform.common.persistence.AuditedTenantEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="eiam_mfa_challenge",indexes=@Index(name="ix_mfa_challenge_hash",columnList="challenge_hash",unique=true))
public class MfaChallenge extends AuditedTenantEntity { @Column(name="user_id",nullable=false) private UUID userId; @Column(name="challenge_hash",nullable=false,length=64) private String challengeHash; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="consumed_at") private Instant consumedAt; protected MfaChallenge(){} public MfaChallenge(UUID userId,String hash,Instant expiresAt){this.userId=userId;this.challengeHash=hash;this.expiresAt=expiresAt;} public boolean consume(Instant now){if(consumedAt!=null||!expiresAt.isAfter(now))return false;consumedAt=now;return true;} public UUID getUserId(){return userId;} public Instant getExpiresAt(){return expiresAt;} }
